const fs = require('fs');

function solve() {
    const buf = fs.readFileSync(0);
    let pos = 0;

    function nextInt() {
        while (pos < buf.length && buf[pos] <= 32) {
            pos++;
        }
        if (pos >= buf.length) return null;
        let sign = 1;
        if (buf[pos] === 45) { // '-'
            sign = -1;
            pos++;
        }
        let res = 0;
        while (pos < buf.length && buf[pos] >= 48 && buf[pos] <= 57) {
            res = res * 10 + (buf[pos] - 48);
            pos++;
        }
        return res * sign;
    }

    const nVal = nextInt();
    if (nVal === null) return;
    const N = nVal;

    if (N <= 2) {
        console.log(0);
        return;
    }

    const X = new Int32Array(N);
    for (let i = 0; i < N; i++) {
        X[i] = nextInt();
    }

    const u = new Int32Array(N);
    const v = new Int32Array(N);

    let u_min = 2e9, u_max = -2e9;
    let v_min = 2e9, v_max = -2e9;

    for (let i = 0; i < N; i++) {
        const y = nextInt();
        const x = X[i];
        const ui = x + y;
        const vi = x - y;
        u[i] = ui;
        v[i] = vi;
        if (ui < u_min) u_min = ui;
        if (ui > u_max) u_max = ui;
        if (vi < v_min) v_min = vi;
        if (vi > v_max) v_max = vi;
    }

    function check(D) {
        const u1 = u_min + D;
        const v1 = v_min + D;
        const u2 = u_max - D;
        const v2 = v_max - D;

        // Case 1: Box 1 at (u_min, v_min), Box 2 at (u_max, v_max)
        let ok1 = true;
        for (let i = 0; i < N; i++) {
            const ui = u[i];
            const vi = v[i];
            const inB1 = (ui <= u1 && vi <= v1);
            const inB2 = (ui >= u2 && vi >= v2);
            if (!inB1 && !inB2) {
                ok1 = false;
                break;
            }
        }
        if (ok1) return true;

        // Case 2: Box 1 at (u_min, v_max), Box 2 at (u_max, v_min)
        let ok2 = true;
        for (let i = 0; i < N; i++) {
            const ui = u[i];
            const vi = v[i];
            const inB1 = (ui <= u1 && vi >= v2);
            const inB2 = (ui >= u2 && vi <= v1);
            if (!inB1 && !inB2) {
                ok2 = false;
                break;
            }
        }
        return ok2;
    }

    let low = 0, high = Math.max(u_max - u_min, v_max - v_min);
    let ans = high;

    while (low <= high) {
        const mid = (low + high) >> 1;
        if (check(mid)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    console.log(ans);
}

solve();
